var beforeGlyphs = font.glyphTable.Count;
font.ClearFontAssetData(true);
UnityEditor.EditorUtility.SetDirty(font);
UnityEditor.EditorUtility.SetDirty(font.atlasTexture);
UnityEditor.AssetDatabase.SaveAssetIfDirty(font);
return new { beforeGlyphs, glyphs = font.glyphTable.Count, characters = font.characterTable.Count, atlasWidth = font.atlasTexture.width, atlasHeight = font.atlasTexture.height };
